import type { ExpeditionPanelUiSnapshot, ExpeditionSnapshot } from '../bus/snapshots.js';

function uiEqual(a: ExpeditionPanelUiSnapshot, b: ExpeditionPanelUiSnapshot): boolean {
  return (
    a.language === b.language
    && a.masteryLabel === b.masteryLabel
    && a.slotsPrefix === b.slotsPrefix
    && a.availableTitle === b.availableTitle
    && a.runningTitle === b.runningTitle
  );
}

function pipsEqual(a?: ('empty' | 'running' | 'done')[], b?: ('empty' | 'running' | 'done')[]): boolean {
  if (a === b) return true;
  if (!a || !b || a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

export function expeditionSnapshotWouldChange(prev: ExpeditionSnapshot, next: ExpeditionSnapshot): boolean {
  return (
    !uiEqual(prev.ui, next.ui)
    || prev.slotsLabel !== next.slotsLabel
    || prev.availableHtml !== next.availableHtml
    || prev.activeHtml !== next.activeHtml
    || prev.activeCount !== next.activeCount
    || prev.maxSlots !== next.maxSlots
    || prev.completedCount !== next.completedCount
    || !pipsEqual(prev.slotPips, next.slotPips)
    || prev.nextCompletionRemainingMs !== next.nextCompletionRemainingMs
    || prev.boardCount !== next.boardCount
    || prev.boardMax !== next.boardMax
    || prev.nextMissionTimerMs !== next.nextMissionTimerMs
  );
}
