import type { GameRuntime } from '../types/game.js';
import type { ExpeditionPanelUiSnapshot, ExpeditionSnapshot } from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import { expeditionSnapshotWouldChange } from '../stores/expeditionSnapshotDiff.js';
import { buildActiveExpeditionsHtml, buildAvailableExpeditionsHtml } from '@snapshot/expedition';

function expeditionT(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t === 'function') {
    const translated = game.t(key);
    if (translated && translated !== key) return translated;
  }
  return fallback;
}

export function buildExpeditionPanelUi(game: GameRuntime): ExpeditionPanelUiSnapshot {
  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  return {
    language,
    masteryLabel: expeditionT(game, 'expeditions.mastery', 'Maîtrises'),
    slotsPrefix: expeditionT(game, 'expeditions.slots', 'Slots :'),
    availableTitle: expeditionT(game, 'expeditions.available', 'Missions Disponibles'),
    runningTitle: expeditionT(game, 'expeditions.running', 'En cours'),
  };
}

export function buildExpeditionSnapshot(game: GameRuntime): ExpeditionSnapshot {
  const activeCount = Array.isArray(game.activeExpeditions) ? game.activeExpeditions.length : 0;
  const maxSlots = typeof game.getMaxExpeditionSlots === 'function' ? game.getMaxExpeditionSlots() : (game.maxExpeditionSlots ?? 3);
  const now = Date.now();
  let completedCount = 0;
  let nextCompletionRemainingMs: number | null = null;
  const slotPips: ('empty' | 'running' | 'done')[] = [];

  for (let i = 0; i < maxSlots; i++) {
    if (i < activeCount) {
      const exp = game.activeExpeditions[i];
      const left = (exp?.endTime ?? 0) - now;
      if (left <= 0) {
        completedCount++;
        slotPips.push('done');
      } else {
        slotPips.push('running');
        if (nextCompletionRemainingMs === null || left < nextCompletionRemainingMs) {
          nextCompletionRemainingMs = left;
        }
      }
    } else {
      slotPips.push('empty');
    }
  }

  return {
    ui: buildExpeditionPanelUi(game),
    slotsLabel: `${activeCount}/${maxSlots}`,
    availableHtml: buildAvailableExpeditionsHtml(game),
    activeHtml: buildActiveExpeditionsHtml(game),
    activeCount,
    maxSlots,
    completedCount,
    slotPips,
    nextCompletionRemainingMs,
    boardCount: Array.isArray(game.availableExpeditions) ? game.availableExpeditions.length : 0,
    boardMax: game.maxAvailableExpeditions ?? 6,
    nextMissionTimerMs: game.expeditionTimer ?? 0,
  };
}

let lastExpeditionSnapshot: ExpeditionSnapshot | null = null;

/** @internal Vitest only */
export function resetExpeditionSnapshotDedupForTests(): void {
  lastExpeditionSnapshot = null;
}

export function notifyExpeditionChanged(game: GameRuntime): void {
  const expedition = buildExpeditionSnapshot(game);
  if (lastExpeditionSnapshot && !expeditionSnapshotWouldChange(lastExpeditionSnapshot, expedition)) return;
  lastExpeditionSnapshot = expedition;
  publish({ type: Evt.EXPEDITION_CHANGED, expedition });
}
